#include <zephyr/kernel.h>
#include <zephyr/sys/heap.h>
#include <zephyr/sys/dlist.h>
#include <zephyr/sys/util.h>
#include <zephyr/logging/log.h>
#include <string.h>

LOG_MODULE_REGISTER(heap, CONFIG_HEAP_LOG_LEVEL);

#define HEAP_CHUNK_HEADER_SIZE  (sizeof(struct heap_chunk))

/*
 * Heap chunk structure.
 *
 * Chunks are always aligned to HEAP_CHUNK_ALIGNMENT.
 * The size field includes the header size.
 * The lowest bit of size indicates if the chunk is free (0) or allocated (1).
 * The second lowest bit indicates if the previous chunk is free (0) or allocated (1).
 */
struct heap_chunk {
    sys_dnode_t node; /* For free list */
    size_t size;      /* Size of the chunk, including header. Lowest bit: allocated/free. Second lowest bit: prev_free/prev_allocated */
};

/*
 * Heap structure.
 */
struct k_heap {
    struct heap_chunk *start_chunk; /* Pointer to the first chunk in the heap */
    struct heap_chunk *end_chunk;   /* Pointer to the memory address just past the end of the heap */
    sys_dlist_t buckets[CONFIG_HEAP_MAX_BUCKETS]; /* Free lists for different chunk sizes */
    size_t free_chunks_size[CONFIG_HEAP_MAX_BUCKETS]; /* Total size of free chunks in each bucket */
    int min_bucket_shift; /* log2(min_chunk_size) */
    int max_buckets;      /* Total number of buckets */
};

// Helper functions (declarations)
static inline size_t chunk_size(struct heap_chunk *chunk);
static inline void set_chunk_size(struct heap_chunk *chunk, size_t size);
static inline bool heap_chunk_is_free(struct heap_chunk *chunk);
static inline void heap_chunk_set_free(struct heap_chunk *chunk);
static inline void heap_chunk_set_allocated(struct heap_chunk *chunk);
static inline bool heap_prev_chunk_is_free(struct heap_chunk *chunk);
static inline void heap_prev_chunk_set_free(struct heap_chunk *chunk);
static inline void heap_prev_chunk_set_allocated(struct heap_chunk *chunk);
static inline struct heap_chunk *heap_next_chunk(struct heap_chunk *chunk);
static inline struct heap_chunk *heap_buddy(struct k_heap *h, struct heap_chunk *chunk);
static inline bool heap_can_merge(struct heap_chunk *chunk, struct heap_chunk *buddy);
static inline struct heap_chunk *heap_merge_chunks(struct heap_chunk *chunk1, struct heap_chunk *chunk2);
static inline struct heap_chunk *heap_split_chunk(struct k_heap *h, struct heap_chunk *chunk, size_t req_size);
static inline int bucket_idx(struct k_heap *h, size_t size);

// Helper functions (definitions)
static inline size_t chunk_size(struct heap_chunk *chunk)
{
    return chunk->size & ~0x3; // Clear the lowest two bits
}

static inline void set_chunk_size(struct heap_chunk *chunk, size_t size)
{
    chunk->size = (chunk->size & 0x3) | size; // Preserve status bits
}

static inline bool heap_chunk_is_free(struct heap_chunk *chunk)
{
    return (chunk->size & 0x1) == 0;
}

static inline void heap_chunk_set_free(struct heap_chunk *chunk)
{
    chunk->size &= ~0x1;
}

static inline void heap_chunk_set_allocated(struct heap_chunk *chunk)
{
    chunk->size |= 0x1;
}

static inline bool heap_prev_chunk_is_free(struct heap_chunk *chunk)
{
    return (chunk->size & 0x2) == 0;
}

static inline void heap_prev_chunk_set_free(struct heap_chunk *chunk)
{
    chunk->size &= ~0x2;
}

static inline void heap_prev_chunk_set_allocated(struct heap_chunk *chunk)
{
    chunk->size |= 0x2;
}

static inline struct heap_chunk *heap_next_chunk(struct heap_chunk *chunk)
{
    return (struct heap_chunk *)((char *)chunk + chunk_size(chunk));
}

static inline struct heap_chunk *heap_buddy(struct k_heap *h, struct heap_chunk *chunk)
{
    size_t c_size = chunk_size(chunk);
    uintptr_t chunk_addr = (uintptr_t)chunk;
    uintptr_t heap_start_addr = (uintptr_t)h->start_chunk;

    // Buddy address is XORed with chunk size relative to heap start
    return (struct heap_chunk *)(heap_start_addr + ((chunk_addr - heap_start_addr) ^ c_size));
}

static inline bool heap_can_merge(struct heap_chunk *chunk, struct heap_chunk *buddy)
{
    // Chunks can merge if they are buddies and both are free and of the same size.
    return chunk_size(chunk) == chunk_size(buddy);
}

static inline struct heap_chunk *heap_merge_chunks(struct heap_chunk *chunk1, struct heap_chunk *chunk2)
{
    struct heap_chunk *merged_chunk = MIN(chunk1, chunk2);
    size_t merged_size = chunk_size(chunk1) + chunk_size(chunk2);

    set_chunk_size(merged_chunk, merged_size);
    heap_chunk_set_free(merged_chunk); // Merged chunk is free

    // Update next chunk's prev_free status
    struct heap_chunk *next = heap_next_chunk(merged_chunk);
    if (next != NULL) {
        heap_prev_chunk_set_free(next);
    }

    return merged_chunk;
}

static inline struct heap_chunk *heap_split_chunk(struct k_heap *h, struct heap_chunk *chunk, size_t req_size)
{
    size_t chunk_s = chunk_size(chunk);
    size_t remaining_size = chunk_s - req_size;

    // Split the chunk
    set_chunk_size(chunk, req_size);
    heap_chunk_set_allocated(chunk);

    struct heap_chunk *new_free_chunk = (struct heap_chunk *)((char *)chunk + req_size);
    set_chunk_size(new_free_chunk, remaining_size);
    heap_chunk_set_free(new_free_chunk);
    heap_prev_chunk_set_allocated(new_free_chunk); // The previous chunk (allocated part) is now allocated

    // Update the next chunk of the new_free_chunk
    struct heap_chunk *next = heap_next_chunk(new_free_chunk);
    if (next != NULL) {
        heap_prev_chunk_set_free(next);
    }

    return new_free_chunk;
}

static inline int bucket_idx(struct k_heap *h, size_t size)
{
    int idx = log2_floor(size) - h->min_bucket_shift;

    if (idx < 0) {
        idx = 0;
    }
    if (idx >= h->max_buckets) {
        idx = h->max_buckets - 1;
    }
    return idx;
}

void k_heap_init(struct k_heap *h, void *mem, size_t bytes)
{
    __ASSERT_NO_MSG(mem != NULL);
    __ASSERT_NO_MSG(bytes >= HEAP_CHUNK_HEADER_SIZE + CONFIG_HEAP_MEM_POOL_MIN_SIZE);
    __ASSERT_NO_MSG(IS_ALIGNED(mem, HEAP_CHUNK_ALIGNMENT));
    __ASSERT_NO_MSG(IS_ALIGNED(bytes, HEAP_CHUNK_ALIGNMENT));

    h->start_chunk = (struct heap_chunk *)mem;
    h->end_chunk = (struct heap_chunk *)((char *)mem + bytes);

    // Initialize buckets
    for (int i = 0; i < CONFIG_HEAP_MAX_BUCKETS; i++) {
        sys_dlist_init(&h->buckets[i]);
        h->free_chunks_size[i] = 0;
    }

    h->min_bucket_shift = LOG2_FLOOR(CONFIG_HEAP_MEM_POOL_MIN_SIZE);
    // Calculate max_buckets based on total size. max_buckets is the count of buckets.
    h->max_buckets = LOG2_FLOOR(bytes) - h->min_bucket_shift + 1;

    // Initialize the entire heap as one free chunk
    struct heap_chunk *initial_chunk = h->start_chunk;
    set_chunk_size(initial_chunk, bytes);
    heap_chunk_set_free(initial_chunk);
    heap_prev_chunk_set_allocated(initial_chunk); // No previous chunk, so consider it allocated

    // Add the initial chunk to its bucket
    int bi = bucket_idx(h, chunk_size(initial_chunk));
    sys_dlist_append(&h->buckets[bi], &initial_chunk->node);
    h->free_chunks_size[bi] += chunk_size(initial_chunk);
}

void *k_heap_alloc(struct k_heap *h, size_t bytes, k_timeout_t timeout)
{
    size_t req_size = ROUND_UP(bytes + HEAP_CHUNK_HEADER_SIZE, HEAP_CHUNK_ALIGNMENT);

    if (req_size < CONFIG_HEAP_MEM_POOL_MIN_SIZE) {
        req_size = CONFIG_HEAP_MEM_POOL_MIN_SIZE;
    }

    int bi = bucket_idx(h, req_size);
    struct heap_chunk *chunk = NULL;

    // Search for a suitable chunk
    for (int i = bi; i < h->max_buckets; i++) {
        if (!sys_dlist_is_empty(&h->buckets[i])) {
            chunk = (struct heap_chunk *)sys_dlist_get(&h->buckets[i]);
            h->free_chunks_size[i] -= chunk_size(chunk);
            break;
        }
    }

    if (chunk == NULL) {
        // No suitable chunk found, try to wait or return NULL
        // For simplicity, returning NULL immediately.
        return NULL;
    }

    // Split if necessary
    while (chunk_size(chunk) >= req_size * 2 && chunk_size(chunk) >= CONFIG_HEAP_MEM_POOL_MIN_SIZE * 2) {
        // Split the chunk into two buddies
        struct heap_chunk *new_free_chunk = heap_split_chunk(h, chunk, chunk_size(chunk) / 2);
        int new_bi = bucket_idx(h, chunk_size(new_free_chunk));
        sys_dlist_append(&h->buckets[new_bi], &new_free_chunk->node);
        h->free_chunks_size[new_bi] += chunk_size(new_free_chunk);
    }

    // Mark the chunk as allocated
    heap_chunk_set_allocated(chunk);

    // Update the next chunk's prev_free status
    struct heap_chunk *next = heap_next_chunk(chunk);
    if (next != NULL && next < h->end_chunk) {
        heap_prev_chunk_set_allocated(next);
    }

    return (char *)chunk + HEAP_CHUNK_HEADER_SIZE;
}

void k_heap_free(struct k_heap *h, void *mem)
{
    if (mem == NULL) {
        return;
    }

    struct heap_chunk *chunk = (struct heap_chunk *)((char *)mem - HEAP_CHUNK_HEADER_SIZE);

    __ASSERT_NO_MSG(!heap_chunk_is_free(chunk)); // Should not be freeing an already free chunk
    __ASSERT_NO_MSG(chunk >= h->start_chunk && chunk < h->end_chunk); // Chunk must be within heap bounds

    heap_chunk_set_free(chunk);

    // Update the next chunk's prev_free status
    struct heap_chunk *next = heap_next_chunk(chunk);
    if (next != NULL && next < h->end_chunk) {
        heap_prev_chunk_set_free(next);
    }

    int bi = bucket_idx(h, chunk_size(chunk));

    // Try to merge with buddies
    while (true) {
        struct heap_chunk *buddy = heap_buddy(h, chunk);

        // Check if buddy is within heap bounds and is free and can be merged
        if (buddy < h->start_chunk || buddy >= h->end_chunk ||
            !heap_chunk_is_free(buddy) || !heap_can_merge(chunk, buddy)) {
            break;
        }

        // Remove buddy from its bucket
        int buddy_bi = bucket_idx(h, chunk_size(buddy));
        sys_dlist_remove(&buddy->node);
        h->free_chunks_size[buddy_bi] -= chunk_size(buddy);

        // Merge chunks
        chunk = heap_merge_chunks(chunk, buddy);
        bi = bucket_idx(h, chunk_size(chunk)); // Update bi for the merged chunk

        // ASSERTION FAIL [bi < bucket_idx(h, h->end_chunk)] @ WEST_TOPDIR/zephyr/lib/heap/heap.c:380
        // The original assertion was using `bucket_idx(h, h->end_chunk)` as the upper bound.
        // `h->end_chunk` is a pointer, not a size, so passing it to `bucket_idx` is incorrect.
        // The intent is to check that `bi` is within the valid range of bucket indices (0 to h->max_buckets - 1).
        // Thus, `bi` must be strictly less than `h->max_buckets`.
        __ASSERT_NO_MSG(bi < h->max_buckets);
    }

    // Add the final (possibly merged) chunk to its bucket
    sys_dlist_append(&h->buckets[bi], &chunk->node);
    h->free_chunks_size[bi] += chunk_size(chunk);
}

// Other heap functions like k_heap_aligned_alloc, k_heap_aligned_free, etc.
// would typically follow here.
